"use client";

import { PrivyProvider } from "@privy-io/react-auth";
import { WagmiProvider } from "@privy-io/wagmi";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { createConfig, http } from "wagmi";
import { arcTestnet, ARC_RPC_URL } from "../lib/arc";
import { WalletProvider } from "../lib/wallet/WalletContext";
import { ConnectModal } from "../components/wallet/ConnectModal";

// Real Flux mark supplied by the user (Phase F §5) — replaces the hand-drawn
// SVG placeholder. Privy renders its login modal in an iframe on Privy's own
// domain, so a relative /brand path would resolve against Privy, not us; a
// base64 data URI sidesteps that entirely with zero env-var dependency. Chose
// this over an absolute NEXT_PUBLIC_APP_URL-based URL deliberately: this repo's
// dev server already runs on a non-default port (see .claude/launch.json), so
// a hardcoded/misconfigured base URL would silently 404 again — exactly the
// class of bug this phase exists to fix. The PNG has a real alpha channel
// (verified) and reads correctly on the dark login card (theme: 'dark' below).
const FLUX_LOGIN_LOGO_DATA_URI = "data:image/png;base64,";

/* wagmi config — using @privy-io/wagmi's createConfig */
export const wagmiConfig = createConfig({
  chains: [arcTestnet],
  transports: {
    // batch: coalesces multiple eth_call requests fired in the same tick into
    // one HTTP POST (a swap quote alone fires 6-8 concurrent reads across
    // routes) — the public Arc RPC rate-limits per HTTP request, so this cuts
    // the actual request count dramatically. retryCount/retryDelay give every
    // call in the app the backoff this RPC needs, not just the two files that
    // had it hand-wired before.
    [arcTestnet.id]: http(ARC_RPC_URL, {
      batch: { wait: 20 },
      retryCount: 4,
      retryDelay: 400,
    }),
  },
});

const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: 1, staleTime: 10_000 } },
});

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <PrivyProvider
      appId="cmossicur025d0cl2x79izo9h"
      config={{
        loginMethods: ["wallet", "email"],
        appearance: {
          theme: "dark",
          accentColor: "#0f766e",
          logo: FLUX_LOGIN_LOGO_DATA_URI,
          walletChainType: "ethereum-only",
          showWalletLoginFirst: true,
        },
        embeddedWallets: {
          createOnLogin: "users-without-wallets",
          requireUserPasswordOnCreate: false,
        },
        defaultChain: arcTestnet,
        supportedChains: [arcTestnet],
        walletConnectCloudProjectId: undefined,
      }}
    >
      <QueryClientProvider client={queryClient}>
        <WagmiProvider config={wagmiConfig} reconnectOnMount>
          <WalletProvider>
            {children}
            <ConnectModal />
          </WalletProvider>
        </WagmiProvider>
      </QueryClientProvider>
    </PrivyProvider>
  );
}